mapper.update:
UPDATE loyalty.member_tier SET status = 'CLOSED', effective_to = #{now}
WHERE tenant_id = #{tenantId} AND program_id = #{programId} AND member_id = #{memberId}
  AND tier_scheme_id = #{schemeId} AND status = 'ACTIVE'

mapper.select:
SELECT id, tenant_id, program_id, member_id, tier_scheme_id, tier_id, evaluation_period_id,
       effective_from, effective_to, status
FROM loyalty.member_tier
WHERE tenant_id = #{tenantId} AND program_id = #{programId} AND member_id = #{memberId}
  AND tier_scheme_id = #{schemeId}
ORDER BY effective_from DESC
